1	export type Monster =
2	  | "sphinx"
3	  | "undead-warrior"
4	  | "zombie"
5	  | "hydra"
6	  | "cyclops"
7	  | "orthrus"
8	  | "chimera";
9	
10	export interface Card {
11	  monster: Monster;
12	  rank?: 1 | 2 | 3;
13	}
14	
15	export const scoreArmy = (army: Card[]): number =>
16	  army.filter((card) => card.monster === "sphinx").length;
17

1	import { describe, it, expect } from "vitest";
2	import { scoreArmy } from "./sphinx-score.js";
3	
4	describe("Sphinx scoring", () => {
5	  // Simplest cases — no Sphinx, no points
6	  it("scores an empty army as 0", () => {
7	    expect(scoreArmy([])).toBe(0);
8	  });
9	  it("scores an army with no Sphinx as 0 — a lone hydra is worth 0", () => {
10	    expect(scoreArmy([{ monster: "hydra" }])).toBe(0);
11	  });
12	  it("scores an army of only non-Sphinx monsters as 0 — hydra, zombie, cyclops, orthrus is worth 0", () => {
13	    expect(
14	      scoreArmy([
15	        { monster: "hydra" },
16	        { monster: "zombie" },
17	        { monster: "cyclops" },
18	        { monster: "orthrus" },
19	      ]),
20	    ).toBe(0);
21	  });
22	
23	  // A single Sphinx, three or fewer types — 1 point each
24	  it("scores a lone Sphinx as 1 — one type is not beyond three", () => {
25	    expect(scoreArmy([{ monster: "sphinx" }])).toBe(1);
26	  });
27	  it.todo("scores a Sphinx with one other type as 1 — sphinx, hydra is worth 1");
28	  it.todo("scores a Sphinx with three types total as 1 — sphinx, hydra, zombie is worth 1");
29	
30	  // A single Sphinx, more than three types — 2 points each
31	  it.todo("scores a Sphinx with four types total as 2 — sphinx, hydra, zombie, cyclops is worth 2");
32	  it.todo("scores a Sphinx with seven types total as 2 — every monster once is worth 2");
33	
34	  // Duplicates do not add types
35	  it.todo("counts repeated monsters as one type — sphinx, hydra, hydra, hydra is worth 1");
36	  it.todo("counts repeated monsters as one type when beyond three — sphinx, hydra, hydra, zombie, cyclops is worth 2");
37	
38	  // Multiple Sphinxes — each scores
39	  it.todo("scores each Sphinx separately — two sphinxes alone are worth 2");
40	  it.todo("scores each Sphinx at 2 when beyond three types — two sphinxes with hydra, zombie, cyclops are worth 4");
41	  it.todo("counts Sphinx duplicates as a single type — three sphinxes alone are worth 3");
42	
43	  // Undead Warrior rank variants are one type
44	  it.todo("counts Undead Warrior ranks as a single type — sphinx, undead-warrior ranks 1, 2, 3 is worth 1");
45	  it.todo("counts Undead Warrior as one type among others — sphinx, undead-warrior ranks 1 and 2, hydra, zombie is worth 2");
46	
47	  // Spec example
48	  it.todo("scores the spec example — sphinx, undead-warrior rank 2, hydra is worth 1");
49	});
